'use strict';
// Preferência do responsável: uma frota única, vínculos de empresa preservados.
// Alterar para true restaura filtro, nomes e campos de empresa na interface.
const SHOW_COMPANY_GROUPS=false;
function companyOptions(){if(!SHOW_COMPANY_GROUPS)return '';const counts=new Map();for(const v of state.vehicles){const name=v.company||'__unassigned';counts.set(name,(counts.get(name)||0)+1)}return `<label class="company-filter"><span>Empresa</span><select id="company-filter" aria-label="Filtrar por empresa"><option value="all">Todas as empresas (${state.vehicles.length})</option>${[...counts.keys()].sort((a,b)=>a.localeCompare(b,'pt-BR')).map(name=>`<option value="${esc(name)}" ${companyFilter===name?'selected':''}>${esc(name==='__unassigned'?'Empresa não informada':name)} (${counts.get(name)})</option>`).join('')}</select></label>`}
function publicResearchView(v){const info=v.publicResearch;if(!info)return '';const sources=(info.sources||[]).filter(s=>/^https:\/\//.test(s.url));const lookup=info.referenceOnly?.plateLookup?.fields;const extra=lookup?[['Marca / modelo da consulta',[lookup.Marca,lookup.Modelo].filter(Boolean).join(' / ')],['Cilindrada',lookup.Cilindrada],['Potência',lookup.Potencia],['Tipo no cadastro',lookup['Tipo Veiculo']],['Carroceria no cadastro',lookup.Carroceria]].filter(([,value])=>value):[];return `<section class="panel"><h2>Complemento de pesquisa pública</h2><p class="help">Consultado em ${fmt(info.checkedOn)}. As fontes públicas podem estar desatualizadas. Confira as informações no documento do veículo.</p><p class="rule-note">${esc(info.note||'')}</p><details><summary>Consultar fontes${extra.length?' e informações de referência':''}</summary>${extra.length?`<dl class="facts">${extra.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`:''}<div class="research-links">${sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`).join('')}</div></details></section>`}
function unresolvedImportIssues(v){return(v.importIssues||[]).filter(issue=>{if(issue.field==='model')return !v.model;if(issue.field==='company')return SHOW_COMPANY_GROUPS&&!v.companyReviewConfirmed;if(issue.field.startsWith('documents.'))return !v.documents[issue.field.split('.')[1]]?.reviewConfirmed;return !v.plateReviewConfirmed})}
function importReviewView(v){const list=unresolvedImportIssues(v);if(!list.length)return '';return `<section class="panel"><h2>Conferência da planilha</h2><p class="help">Algumas células precisam de confirmação no documento original.</p>${list.map(i=>`<p class="rule-note">${esc(i.message)}</p>`).join('')}${v.source?.rows?.length?`<p class="help">Referência: linha(s) ${esc(v.source.rows.join(', '))} da transcrição das fotografias.</p>`:''}</section>`}
function editSheetDocument(v,key){const rule=RULES.documents.find(r=>r.key===key),old=v.documents[key]||{};modal(rule.name+' · '+v.plate,'Informe a validade indicada no documento.',`<p class="full rule-note">Na planilha: ${esc(old.rawValue||'sem data')}${old.reviewNote?' · '+esc(old.reviewNote):''}${old.annotation?' · A marcação '+esc(old.annotation)+' foi preservada sem presumir significado.':''}</p>${field('due','Validade confirmada','date',old.due||'','required',true)}${field('notes','Observações (opcional)','text','','maxlength="300"',true)}`,f=>{v.documents[key]={...old,due:f.get('due'),reviewConfirmed:true,status:'confirmed',reviewNote:'',notes:f.get('notes').trim()};log(v,`${rule.name}: validade confirmada em ${fmt(f.get('due'))}`);commit('Validade atualizada para toda a empresa.')},'Salvar validade')}
function completeVehicleIdentity(v){const specs=[['model','Modelo','text','maxlength="100"'],['category','Tipo de veículo','text','maxlength="50" placeholder="Transporte, passeio, carga ou implemento"'],['year','Ano / modelo','number','min="1950" max="2100" step="1"'],['chassis','Chassi','text','maxlength="17" minlength="17"'],['gearbox','Número do câmbio','text','maxlength="60"'],['capacity','Capacidade (lugares)','number','min="1" max="200" step="1"'],['fuelType','Combustível','text','maxlength="50"']].filter(([key])=>v[key]==null||v[key]==='');modal('Completar identificação',v.plate+' · Preencha somente o que souber.',specs.map(([key,label,type,extra])=>field(key,label,type,'',extra)).join('')+'<p class="full help">Os campos podem continuar vazios. Os valores preenchidos passam a fazer parte da identificação fixa do veículo.</p>',f=>{const changes={};for(const[key,,type]of specs){const value=String(f.get(key)||'').trim();if(!value)continue;if(key==='chassis'&&!/^[A-HJ-NPR-Z0-9]{17}$/i.test(value))throw Error('Confira o chassi: são 17 letras e números, sem I, O ou Q.');changes[key]=type==='number'?Number(value):value}Object.assign(v,changes);log(v,'Identificação complementada');commit('Identificação atualizada.')},'Salvar informações')}
